function resourceReady(f,k){if(f.aether)return k==='attack'?!f.aether.liquid:window.AetherCombat.ready(f,k);if(f.fairi)return window.FairiCombat.ready(f,k);if(k==='attack')return true;if(k==='q'&&f.type==='soul')return f.cd.q<=1e-7;if(f.cd[k]>1e-7)return false;if(f.type==='soul'&&k==='w'&&f.blade&&f.blade.age<.3)return false;if(f.aether&&k==='q'&&f.aether.q)status=f.aether.q.count+' tinh thể còn lại';if(f.aether&&k==='w'&&f.aether.cage&&f.aether.cage.breakAt>time)status='Giữ chân '+(f.aether.cage.breakAt-time).toFixed(1)+'s';if(f.frost&&k==='w'&&f.frost.zones.some(z=>z.k==='w'))return false;return true;}
