function request(f,k){if(f?.melanta?.a?.k==='w'&&k==='r'&&f.cd.r<=0&&((f.melanta.a.locked&&f.melanta.a.t>=.6)||f.melanta.a.t>=.81)&&!f.melanta.a.hit){f.combat.buffer={k,until:time+.32};return;}if(!f||phase!=='fight'||f.hp<=0)return;if(isStunned(f)){if(moves.includes(k))f.combat.buffer={k,until:time+combatTuning().buffer};return;}if(k==='jump'){if(f.aether?.liquid||f.aether?.hover||f.fairi&&f.action||f.melanta?.a||f.mox?.action?.grab||f.mox?.action?.k==='e'||f.rootUntil>time||(f.type==='cylast'&&f.action&&f.action.k!=='attack'))return;if(f.ground||f.jumps<2){f.vy=-900;f.ground=false;f.jumps++;combatSound('jump',f.x);emit('dust',f.x,f.y,colors[f.type],55);}else f.jumpUntil=time+.14;return;}if(!moves.includes(k))return;const result=begin(f,k);if(result===null)f.combat.buffer={k,until:time+combatTuning().buffer};else if(result)f.combat.buffer=null;}
