function showMessage(sub,title,detail,button){rollbackMessage={sub,title,detail,button};if(rollbackDriving)return;$('pauseSettings').hidden=phase!=='paused';document.body.classList.toggle('paused',phase==='paused');$('back').textContent=phase==='paused'?'VỀ TRANG CHỦ':'CHỌN LẠI';$('message').hidden=false;$('messageSub').textContent=sub;$('messageTitle').textContent=title;$('messageDetail').textContent=detail;$('continue').textContent=button;renderPauseSkills();}
function pause(){window.virtualStick?.reset();if(onlineActive()&&window.riftNet.fullRollback&&!rollbackDriving){window.riftNet.action('pause');return;}if(onlineGuest()){window.riftNet.action('pause');return;}if(phase==='fight'||phase==='countdown'||phase==='finishing'){pausedFrom=phase;phase='paused';if(!rollbackDriving)window.sagaAudio?.stopCombat();keys={};for(const f of fighters)f.combat.buffer=null;showMessage('SAGA FIGHT','TẠM DỪNG','Trận đấu sẽ tiếp tục từ vị trí hiện tại.','TIẾP TỤC');}else if(phase==='paused'){$('message').hidden=true;document.body.classList.remove('paused');phase=pausedFrom;focusGame();}}
function step(dt){simTick++;if(!rollbackDriving)window.riftNet?.beforeStep?.();const finishing=phase==='finishing';if(finishing){finishLeft=Math.max(0,finishLeft-dt);dt*=FINISH_CONFIG.speed;}time+=dt;effects.forEach(e=>e.age+=dt);effects=effects.filter(e=>e.age<e.life);shake*=Math.exp(-dt*14);moxShake*=Math.exp(-dt*8);if(phase==='countdown'){countdown=Math.max(0,countdown-dt);if(countdown<=.65+1e-8){combatSound('round_start');phase='fight';}updateCountdownBanner();return;}if(finishing&&(melantaKiller!=null||aetherKiller!=null||fairiKiller!=null)){if(fairiKiller!=null&&finishLeft<=2.08&&!fighters[fairiKiller].fairi.finishSound){fighters[fairiKiller].fairi.finishSound=true;combatSound('soulblade_slash_1');}if(aetherKiller!=null&&finishLeft<=.35&&!fighters[aetherKiller].aether.finishSound){fighters[aetherKiller].aether.finishSound=true;combatSound('aether_break');}if(finishLeft<=0)finishRound();return;}if(finishing){for(const f of fighters)updateFighter(f,dt);for(const s of shots){s.age+=dt;s.x+=s.vx*dt;s.y+=(s.vy||0)*dt;}shots=shots.filter(s=>s.age<2.6&&s.x>0&&s.x<W);if(finishLeft<=0)finishRound();return;}if(phase!=='fight')return;if(countdown>0){countdown=Math.max(0,countdown-dt);updateCountdownBanner();}reconcileCombos();dummyDefense();
if(mode!=='sandbox')remaining=Math.max(0,remaining-dt);if(rollbackInputs){fighters[0].move=rollbackInputs[0].m;fighters[1].move=rollbackInputs[1].m;}else{fighters[0].move=(keys.KeyD||((mode==='pve'||mode==='online'||mode==='sandbox')&&keys.ArrowRight)?1:0)-(keys.KeyA||((mode==='pve'||mode==='online'||mode==='sandbox')&&keys.ArrowLeft)?1:0);if(mode==='online')fighters[1].move=remoteMove;else if(mode==='pvp')fighters[1].move=(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0);else if(mode!=='sandbox'||sandboxOptions.ai)ai(dt);else fighters[1].move=0;}for(const f of fighters){if(mode==='sandbox'&&sandboxOptions.free)resetCooldowns(f);updateFighter(f,dt);if(mode==='sandbox'){if(sandboxOptions.free)resetCooldowns(f);if(time-f.lastHurt>1.8)f.hp=f.aether?window.AetherBase.CONFIG.hp:f.fairi?900:1000;}}
for(const s of shots){const prev=s.x;s.age+=dt;s.x+=s.vx*dt;s.y+=(s.vy||0)*dt;if(s.kind==='frost')s.remaining-=Math.hypot(s.vx,s.vy)*dt;const e=fighters[1-s.owner];if(decoyProjectile(fighters[s.owner],prev,s.y,s.x,s.y,s.damage??90,s.hitId||'shot:'+s.owner+':'+Math.round((time-s.age)*1000)))s.age=5;if(s.age<2.6&&(s.kind==='frost'?e.x>=Math.min(prev,s.x)-24&&e.x<=Math.max(prev,s.x)+24:Math.abs(e.x-s.x)<42)&&s.y>e.y-205&&s.y<e.y+10){damage(fighters[s.owner],e,s.damage??(s.kind==='frost'?65:90),s.kind==='frost'?0:60,false,false,{use:s.use,hitId:s.hitId,last:true});emit(s.kind==='frost'?'frostBurst':'spark',s.x,s.y,s.kind==='frost'?colors.cylast:colors.thunder,130,{life:.4});s.age=5;}}shots=shots.filter(s=>s.age<2.6&&s.x>0&&s.x<W&&(s.kind!=='frost'||s.remaining>0));
reconcileCombos();if(mode!=='sandbox'){if(fighters.some(f=>f.hp<=0))beginFinisher();else if(remaining<=0)finishRound();}}
function hud(){if(rollbackDriving)return;if(!fighters.length)return;for(const f of fighters){if(f.mox)textIfChanged($('n'+f.id),'MOX · '+(f.mox.p.form?'ĐÁNH XA':'CẬN CHIẾN'));const max=f.aether?window.AetherBase.CONFIG.hp:f.fairi?900:1000,width=f.hp/max*100+'%';if($('hp'+f.id).style.width!==width)$('hp'+f.id).style.width=width;textIfChanged($('num'+f.id),Math.ceil(f.hp)+' / '+max);textIfChanged($('wins'+f.id),[0,1].map(i=>(window.riftNet?.fullRollback&&rollbackCommitted?rollbackCommitted.score:score)[f.id]>i?'●':'○').join(' '));const buttons=$('skills'+f.id).children;for(let i=0;i<buttons.length;i++){const k=moves[i],left=f.cd[k],charge=k==='q'&&f.fairi,warp=k==='w'&&f.blade;const chainReady=k==='attack'&&f.normal?.use.confirmed&&f.normal.n<3&&f.normal.age>=normalConfig(f).windows[f.normal.n-1][0];buttons[i].classList.toggle('cancel-ready',cancelReady(f,k)||chainReady);textIfChanged(buttons[i].querySelector('span'),f.aether&&k==='q'&&f.aether.q?f.aether.q.count+' ◆':f.aether&&k==='w'&&f.aether.cage&&f.aether.cage.breakAt>time?'GIỮ '+(f.aether.cage.breakAt-time).toFixed(1):f.fairi&&((k==='w'&&f.fairi.wActive)||(k==='e'&&f.fairi.eActive))?'ACTIVE':chainReady?'NỐI N'+(f.normal.n+1):f.frost&&k==='w'&&f.frost.zones.some(z=>z.k==='w')?'ACTIVE':warp?'RECAST':charge&&left>0?left.toFixed(1)+'s':charge?f.charges+'/'+(f.fairi?3:2)+(f.qRecharge.length?' · '+Math.min(...f.qRecharge).toFixed(1):''):left>0?left.toFixed(1)+'s':'READY');buttons[i].classList.toggle('cooling',!chainReady&&(charge?!f.charges||left>0:left>0));buttons[i].classList.toggle('active',f.action?.k===k||!!warp);}}textIfChanged($('timer'),mode==='sandbox'?'∞':Math.ceil(remaining).toString().padStart(2,'0'));textIfChanged($('round'),mode==='sandbox'?'LUYỆN TẬP':'HIỆP '+String(round).padStart(2,'0'));sandboxHUD();aiDebugHUD();}
function line(points,color,width=2,glow=10){ctx.save();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineJoin='round';ctx.lineCap='round';ctx.shadowColor=color;ctx.shadowBlur=glow;ctx.beginPath();for(let i=0;i<points.length;i++)i?ctx.lineTo(...points[i]):ctx.moveTo(...points[i]);ctx.stroke();ctx.restore();}
// Bounded integer-phase raster cache. Smooth temporal blend keeps endpoints anchored.
const boltSprites=new Map();let boltPixels=0;
function bolt(x,y,tx,ty,color,width=3,seed=0){
 const dx=tx-x,dy=ty-y,length=Math.hypot(dx,dy);if(length<.1)return;
 // Two shared horizontal atlases: moving/rotating endpoints no longer allocate new glow textures.
 const span=length>240?512:128,phase=Math.max(0,seed)%6,frame=graphicsQuality==='low'?Math.floor(phase):Math.round(phase*2)/2;
 ctx.save();ctx.translate(x,y);ctx.rotate(Math.atan2(dy,dx));ctx.scale(length/span,1);boltFrame(0,0,span,0,color,width*1.5,frame);ctx.restore();
}
function boltFrame(x,y,tx,ty,color,width,seed){const dx=tx-x,dy=ty-y,len=Math.hypot(dx,dy),scale=1;const key=[dx.toFixed(2),dy.toFixed(2),color,width,seed,scale.toFixed(3)].join(':');let sprite=boltSprites.get(key);
if(sprite){boltSprites.delete(key);boltSprites.set(key,sprite);ctx.drawImage(sprite.image,x+sprite.x,y+sprite.y,sprite.w,sprite.h);return;}
// Seeded multiscale displacement: fixed terminals, broad bends and small irregular forks.
const paths=lightningMorphPaths(dx,dy,seed),points=paths.flat(),padding=42,minX=Math.min(...points.map(p=>p[0]))-padding,minY=Math.min(...points.map(p=>p[1]))-padding,maxX=Math.max(...points.map(p=>p[0]))+padding,maxY=Math.max(...points.map(p=>p[1]))+padding;
const image=document.createElement('canvas');image.width=Math.max(1,Math.ceil((maxX-minX)*scale));image.height=Math.max(1,Math.ceil((maxY-minY)*scale));const pixels=image.width*image.height;
if(pixels>1000000){for(let j=0;j<paths.length;j++){line(paths[j].map(p=>[p[0]+x,p[1]+y]),'#ffd65a',width*(j?.4:1),10);line(paths[j].map(p=>[p[0]+x,p[1]+y]),'#fffbd7',Math.max(.6,width*(j?.12:.3)),0);}return;}
const g=image.getContext('2d');g.setTransform(scale,0,0,scale,-minX*scale,-minY*scale);g.lineJoin='round';g.lineCap='round';
for(let j=0;j<paths.length;j++){g.beginPath();for(let i=0;i<paths[j].length;i++)i?g.lineTo(...paths[j][i]):g.moveTo(...paths[j][i]);g.strokeStyle='#e3ac29';g.lineWidth=width*(j?.72:1.9);g.shadowColor='#ffe15c';g.shadowBlur=j?7:16;g.stroke();g.strokeStyle='#ffe989';g.lineWidth=width*(j?.34:.8);g.shadowBlur=0;g.stroke();g.strokeStyle='#fffbe2';g.lineWidth=Math.max(.6,width*(j?.13:.32));g.stroke();}

while(boltSprites.size&&(boltPixels+pixels>4000000||boltSprites.size>=96)){const oldest=boltSprites.keys().next().value;boltPixels-=boltSprites.get(oldest).pixels;boltSprites.delete(oldest);}
sprite={image,x:minX,y:minY,w:image.width/scale,h:image.height/scale,pixels};boltSprites.set(key,sprite);boltPixels+=pixels;ctx.drawImage(image,x+minX,y+minY,sprite.w,sprite.h);}
// Visual-only, bounded geometry. No RNG from combat and no per-frame particles.
function lightningPaths(dx,dy,seed){
 const len=Math.hypot(dx,dy),ux=dx/(len||1),uy=dy/(len||1);let state=(Math.imul(seed+1,1597334677)^0x7f4a7c15)>>>0;
 const rand=()=>{state=(Math.imul(state,1664525)+1013904223)>>>0;return state/4294967296;};
 let points=[[0,0],[dx,dy]],amp=Math.min(100,len*.19);
 for(let pass=0;pass<6;pass++){const next=[points[0]];for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],r=rand()-.5,offset=(pass===0?Math.sign(r)*(.55+Math.abs(r)*.9):r*2)*amp;next.push([(a[0]+b[0])/2-uy*offset,(a[1]+b[1])/2+ux*offset],b);}points=next;amp*=.47;}
 const paths=[points],count=Math.min(5,Math.floor(len/120)+1);
 for(let j=0;j<count;j++){const index=3+Math.floor(rand()*25),a=points[index],side=rand()<.5?-1:1,length=Math.min(95,len*(.10+rand()*.10)),fork=[a];for(let k=1;k<=5;k++){const u=k/5;fork.push([a[0]+ux*length*u*.58-uy*(side*length*u*.6+(rand()-.5)*length*.18),a[1]+uy*length*u*.58+ux*(side*length*u*.6+(rand()-.5)*length*.18)]);}paths.push(fork);}
 return paths;
}
function lightningMorphPaths(dx,dy,phase){const a=Math.floor(phase)%6,u=phase-Math.floor(phase),t=u*u*(3-2*u),left=lightningPaths(dx,dy,a),right=lightningPaths(dx,dy,(a+1)%6);return left.map((path,j)=>path.map((p,i)=>[p[0]+(right[j][i][0]-p[0])*t,p[1]+(right[j][i][1]-p[1])*t]));}
