function thunderClothPoint(p,w,h,top,dir,c,sway){return [p[0]*w+(c.bend*dir+sway)*p[2],top+p[1]*h+c.lift*p[3]];}
function drawThunderCloth(g,img,w,h,top,f,c,pose){
 const contours=THUNDER_DRAPE[pose];if(!contours)return;
 // A nearly still idle hem hangs under gravity; wind follows one smooth arc without folds.
 const sway=Math.sin(time*2.1)*.32+Math.sin(time*1.3)*.15;
 g.beginPath();for(const contour of contours){for(let i=0;i<contour.length;i++){const p=contour[i],x=p[0]*w+(c.bend*f.dir+sway)*p[2],y=top+p[1]*h+c.lift*p[3];i?g.lineTo(x,y):g.moveTo(x,y);}g.closePath();}g.fillStyle='#ead98e';g.fill('evenodd');
}
// Reference poses keep individual proportions; the body hovers and the orb sits ABOVE the outstretched hand.
