// Desktop fullscreen keeps the header, dialogs and lobby in the same subtree.
async function toggleFullscreen(){
 try{
  if(document.fullscreenElement){await document.exitFullscreen();return;}
  if(document.body.classList.contains('immersive')){document.body.classList.remove('immersive');return;}
  const desktop=window.matchMedia?.('(hover: hover) and (pointer: fine)')?.matches===true;
  const target=desktop?document.documentElement:$('arena');
  if(target.requestFullscreen)await target.requestFullscreen();
  else document.body.classList.add('immersive');
 }catch{document.body.classList.add('immersive');}
 finally{invalidateViewport();}
}
